import AVFoundation
import XCTest
@testable import TygerVoice

/// End-to-end numeric parity for the path-C chain (Parakeet tap + distilled
/// student step) against the Python training harness. Fixtures are generated by
/// `~/dev/ml/pathc/student_fixture.py` from the same checkpoint that ships in
/// `bench-results/pathc/TygerStepStudent.mlpackage` (`student_export.py`).
final class ParakeetStudentTests: XCTestCase {
    func testStudentChainMatchesTheHarness() throws {
        let here = URL(fileURLWithPath: #filePath)
        let runtime = here.deletingLastPathComponent().appendingPathComponent("runtime")
        let repo = here.deletingLastPathComponent().deletingLastPathComponent()
            .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()

        // the shipped Parakeet bundles: FluidAudio's cache or the harness copy
        var preURL: URL?
        var encURL: URL?
        let home = FileManager.default.homeDirectoryForCurrentUser
        for base in [
            repo.appendingPathComponent("bench-results/parakeet"),
            home.appendingPathComponent("dev/ml/pathc/data/parakeet"),
            home.appendingPathComponent("Library/Application Support/FluidAudio/Models/parakeet-redux-coreml"),
            home.appendingPathComponent(".idfon/models/parakeet-redux-coreml"),
        ] {
            if FileManager.default.fileExists(atPath: base.appendingPathComponent("Encoder.mlmodelc").path) {
                preURL = base.appendingPathComponent("Preprocessor.mlmodelc")
                encURL = base.appendingPathComponent("Encoder.mlmodelc")
                break
            }
        }
        let stepURL = repo.appendingPathComponent("bench-results/pathc/TygerStepStudent.mlpackage")
        guard let pre = preURL, let enc = encURL,
              FileManager.default.fileExists(atPath: stepURL.path) else {
            throw XCTSkip("parakeet bundles or student step not present "
                + "(~/dev/ml/pathc: fixture.py + student_export.py)")
        }

        let exp = try JSONDecoder().decode(
            Expectations.self, from: try Data(contentsOf: runtime.appendingPathComponent("expectations-student.json")))
        let user = try readWav(runtime.appendingPathComponent("ch0.wav"))
        let agent = try readWav(runtime.appendingPathComponent("ch1.wav"))

        let model = try ParakeetStudentTurnModel(preprocessorURL: pre, encoderURL: enc, stepURL: stepURL)
        let rt = TurnRuntime(model: model)

        var got: [[Float]] = []
        var winU: [Float] = []
        var winA: [Float] = []
        let windowSamples = 8 * TurnRuntime.sampleRate
        var h = 0
        while (h + 1) * exp.hopSamples <= min(user.count, agent.count) {
            let s = h * exp.hopSamples
            winU.append(contentsOf: user[s..<s + exp.hopSamples])
            winA.append(contentsOf: agent[s..<s + exp.hopSamples])
            if winU.count > windowSamples { winU.removeFirst(winU.count - windowSamples) }
            if winA.count > windowSamples { winA.removeFirst(winA.count - windowSamples) }
            got.append(contentsOf: rt.feed(
                userHop: Array(user[s..<s + exp.hopSamples]),
                agentHop: Array(agent[s..<s + exp.hopSamples]),
                prevState: { _ in 0 }))
            h += 1
            if got.count >= exp.frames.count { break }
        }
        XCTAssertEqual(got.count, exp.frames.count, "frame count")

        // The chain is exact (tap: 0.0 on CPU; step export: 8e-6 vs torch) —
        // anything over 0.01 is a wiring bug, not tier drift.
        var worst: Double = 0
        for (g, w) in zip(got, exp.frames) {
            for k in 0..<8 {
                worst = max(worst, abs(Double(g[k]) - w[k]))
            }
        }
        XCTAssertLessThan(worst, 0.01, "student chain drifted vs the harness")

        // tap spot check: the rows the runtime consumed on the last hop
        let rows = model.encode(winU)
        XCTAssertEqual(exp.windowSamples, winU.count, "spot-check window")
        let spot = exp.tapRows
        var tapWorst: Double = 0
        for (r, row) in spot.enumerated() {
            let gotRow = rows[rows.count - spot.count + r]
            for k in 0..<min(32, gotRow.count) { // first 32 dims: enough to catch a wiring bug
                tapWorst = max(tapWorst, abs(Double(gotRow[k]) - Double(row[k])))
            }
        }
        XCTAssertLessThan(tapWorst, 0.01, "tap rows drifted vs the harness")
    }
}

private struct Expectations: Decodable {
    let hopSamples: Int
    let frames: [[Double]]
    let tapRows: [[Double]]
    let windowSamples: Int
    let student: String?
    let studentEpoch: Int?
}

private func readWav(_ url: URL) throws -> [Float] {
    let f = try AVAudioFile(forReading: url)
    let n = AVAudioFrameCount(f.length)
    let buf = AVAudioPCMBuffer(pcmFormat: f.processingFormat, frameCapacity: n)!
    try f.read(into: buf)
    let ch = buf.floatChannelData![0]
    return (0..<Int(n)).map { ch[$0] }
}
